function shouldKeepPool(allocNs, poolNs, opsPerSec) {
  const freshCostPerSec = allocNs * opsPerSec;
  const poolCostPerSec = poolNs * opsPerSec;
  // keep the pool if it saves time
  return poolCostPerSec > freshCostPerSec;
}

tasks.verify:
const slower = shouldKeepPool(80, 120, 1_000_000);
const faster = shouldKeepPool(200, 60, 1_000_000);
const ok = slower === false && faster === true;
console.log(ok ? 'PASS' : 'FAIL slower=' + slower + ' faster=' + faster);

