var bufPool = sync.Pool{
	New: func() any { return make([]byte, 0, 4096) },
}

func handle(req Request) Response {
	buf := bufPool.Get().([]byte)
	buf = append(buf, req.Body...)        // reuse the pooled buffer
	resp := process(buf)
	bufPool.Put(buf)                      // return it for reuse
	return resp
}
